return ['domain'=>'firmatlas-for-woocommerce','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr_FR','project-id-version'=>'FirmAtlas for WooCommerce 0.1.0','pot-creation-date'=>'2026-11-12T17:38:16+00:00','po-revision-date'=>'2026-11-09 14:00+0100','messages'=>['FirmAtlas for WooCommerce'=>'FirmAtlas for WooCommerce','https://github.com/FirmAtlas/firmatlas-for-woocommerce'=>'https://github.com/FirmAtlas/firmatlas-for-woocommerce','Belgian company search at checkout: customers pick their company and the billing details fill themselves. Adds a VAT number field and checks Belgian VAT numbers. Company data from the KBO/BCE through the Firmatlas API.'=>'Recherche d\'entreprises belges au paiement : les clients choisissent leur entreprise et les données de facturation se remplissent toutes seules. Ajoute un champ pour le numéro de TVA et vérifie les numéros de TVA belges. Données d\'entreprise issues de la BCE via l\'API Firmatlas.','Arne Van Daele'=>'Arne Van Daele','https://arnevandaele.com'=>'https://arnevandaele.com','VAT number'=>'Numéro de TVA','VAT number (optional)'=>'Numéro de TVA (facultatif)','FirmAtlas: the VAT number %s did not check out (KBO/VIES). Check it before invoicing without VAT.'=>'FirmAtlas : le numéro de TVA %s n\'est pas valable selon la BCE ou VIES. Vérifiez-le avant de facturer sans TVA.','valid'=>'valable','not valid'=>'non valable','not checked'=>'non vérifié','not checked (outside Belgium)'=>'non vérifié (hors Belgique)','Enterprise number'=>'Numéro d\'entreprise','Settings'=>'Réglages','Testing…'=>'Test en cours…','Not allowed.'=>'Non autorisé.','Add and save a secret key first.'=>'Ajoutez et enregistrez d\'abord une clé secrète.','The API could not be reached: %s'=>'L\'API est injoignable : %s','The API refused the request.'=>'L\'API a refusé la demande.','Connected. The secret key works.'=>'Connecté. La clé secrète fonctionne.','Valid VAT number'=>'Numéro de TVA valable','FirmAtlas'=>'FirmAtlas','Company search at checkout'=>'Recherche d\'entreprises au paiement','Customers search Belgian companies by name or number in the company field, and the billing address fills itself. Get your keys at %s.'=>'Les clients cherchent des entreprises belges par nom ou par numéro dans le champ entreprise, et l\'adresse de facturation se remplit toute seule. Obtenez vos clés sur %s.','Publishable key'=>'Clé publique','Starts with kbo_pk_live_. Used in the browser; allow this shop\'s address as an origin for the key.'=>'Commence par kbo_pk_live_. Utilisée dans le navigateur ; autorisez l\'adresse de cette boutique comme origine de la clé.','Secret key'=>'Clé secrète','Starts with kbo_sk_live_. Stays on this server; used to check VAT numbers.'=>'Commence par kbo_sk_live_. Reste sur ce serveur ; sert à vérifier les numéros de TVA.','Company search'=>'Recherche d\'entreprises','Search companies in the checkout\'s company field'=>'Chercher des entreprises dans le champ entreprise du paiement','Language'=>'Langue','Language of company names, addresses and the search list.'=>'Langue des noms d\'entreprise, des adresses et de la liste de recherche.','Site language'=>'Langue du site','VAT number field'=>'Champ du numéro de TVA','Add an optional VAT number field to checkout'=>'Ajouter un champ facultatif pour le numéro de TVA au paiement','When a Belgian VAT number is not valid'=>'Quand un numéro de TVA belge n\'est pas valable','Checked against the KBO register and VIES. If the check cannot be done (the API or VIES is down), checkout always goes ahead. VAT numbers from other countries are not checked.'=>'Vérifié dans la BCE et dans VIES. Si la vérification est impossible (l\'API ou VIES est indisponible), la commande passe toujours. Les numéros de TVA d\'autres pays ne sont pas vérifiés.','Accept the order and add an order note'=>'Accepter la commande et ajouter une note','Refuse the order until the number is fixed'=>'Refuser la commande tant que le numéro n\'est pas corrigé','Don\'t check'=>'Ne pas vérifier','Advanced'=>'Avancé','API address'=>'Adresse de l\'API','Leave empty for the hosted Firmatlas API. Set it to use a self-hosted engine behind your own gateway.'=>'Laissez vide pour l\'API Firmatlas hébergée. Remplissez-la pour utiliser votre propre moteur derrière votre propre passerelle.','Test connection'=>'Tester la connexion','Tests the saved secret key. Save first after changing it.'=>'Teste la clé secrète enregistrée. Enregistrez d\'abord si vous l\'avez modifiée.','This is not a valid Belgian VAT number. It looks like BE0123.456.749.'=>'Ce n\'est pas un numéro de TVA belge valable. Il ressemble à BE0123.456.749.','No Belgian company is registered under this VAT number.'=>'Aucune entreprise belge n\'est inscrite sous ce numéro de TVA.','This VAT number is not active for intra-EU trade according to VIES.'=>'Selon VIES, ce numéro de TVA n\'est pas actif pour les échanges intracommunautaires.','receives Peppol invoices'=>'reçoit des factures Peppol','not on Peppol'=>'pas sur Peppol','Peppol'=>'Peppol']];